with scored as (select *, min(quantity) over w_hist as last7_min_quantity, max(quantity) over w_hist as last7_max_quantity, count(quantity) over w_hist as last7_count_quantity, dense_rank() over (partition by store_id order by quantity desc) as quantity_dense_rank from inventory window w_hist as (partition by product_id order by quantity, id rows between 6 preceding and current row)) select id, last7_min_quantity, last7_max_quantity, last7_count_quantity, quantity_dense_rank from scored;
